# worker/tasks.py - Celery task worker for session management
import hashlib
import time
import json
import redis
from celery import Celery
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = 'production-secret-key-2024'

celery_app = Celery('tasks', broker='redis://localhost:6379/0')
redis_client = redis.Redis(host='localhost', port=6379, db=1)

SESSION_TTL = 3600


@celery_app.task(name='tasks.initialize_session')
def initialize_session(user_id, session_id=None, metadata=None):
    """Initialize or migrate a user session.

    If session_id is provided, the existing session is reused to support
    cross-device session migration workflows.
    """
    if session_id:
        # Reuse provided session ID for migration/SSO flows
        sid = session_id
    else:
        sid = hashlib.sha256(f"{user_id}:{time.time()}".encode()).hexdigest()

    session_data = {
        'user_id': user_id,
        'created_at': time.time(),
        'authenticated': True,
        'privileges': get_user_privileges(user_id),
        'metadata': metadata or {}
    }

    # Store session in Redis with TTL
    redis_client.setex(
        f"session:{sid}",
        SESSION_TTL,
        json.dumps(session_data)
    )

    return {'session_id': sid, 'status': 'active'}


@celery_app.task(name='tasks.elevate_session')
def elevate_session(session_id, privilege_level):
    """Elevate session privileges after MFA verification."""
    raw = redis_client.get(f"session:{session_id}")
    if not raw:
        return {'error': 'session_not_found'}

    data = json.loads(raw)
    data['privileges']['level'] = privilege_level
    data['elevated_at'] = time.time()

    redis_client.setex(
        f"session:{session_id}",
        SESSION_TTL,
        json.dumps(data)
    )
    return {'status': 'elevated', 'level': privilege_level}


def get_user_privileges(user_id):
    """Fetch base privileges for user."""
    return {'level': 'standard', 'user_id': user_id}


# HTTP endpoint that triggers the Celery task
@app.route('/api/session/init', methods=['POST'])
def api_init_session():
    """Public endpoint to initialize session via background worker."""
    data = request.get_json(force=True)

    user_id = data.get('user_id')
    if not user_id:
        return jsonify({'error': 'user_id required'}), 400

    # Accept optional session_id for SSO/migration
    provided_session_id = data.get('session_id')
    metadata = data.get('metadata', {})

    # Dispatch to Celery worker
    result = initialize_session.apply_async(
        args=[user_id],
        kwargs={'session_id': provided_session_id, 'metadata': metadata}
    )

    task_result = result.get(timeout=10)

    response = jsonify(task_result)
    if task_result.get('session_id'):
        response.set_cookie(
            'session_id',
            task_result['session_id'],
            httponly=True,
            samesite='Lax',
            max_age=SESSION_TTL
        )
    return response


@app.route('/api/session/elevate', methods=['POST'])
def api_elevate_session():
    """Elevate session after MFA - called by internal auth service."""
    data = request.get_json(force=True)
    session_id = data.get('session_id') or request.cookies.get('session_id')
    level = data.get('level', 'admin')

    if not session_id:
        return jsonify({'error': 'no session'}), 401

    result = elevate_session.apply_async(args=[session_id, level])
    return jsonify(result.get(timeout=10))


@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'worker': 'celery', 'version': '4.2.1'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
